The C++ program below implements a circular queue. Capacity check off-by-one errors and an incorrect peek index prevent the queue from filling to capacity or inspecting the front element. Fix the bug so the circular queue enqueues, dequeues, and peeks correctly.

Buggy program:
```cpp
#include <iostream>
#include <vector>
using namespace std;

class CircularQueue {
    vector<int> data;
    int frontIndex = 0;
    int rearIndex = 0;
    int count = 0;

public:
    CircularQueue(int capacity) : data(capacity) {}

    bool enqueue(int value) {
        if (count == data.size() - 1)
            return false;

        data[rearIndex] = value;
        rearIndex = (rearIndex + 1) % data.size();
        count++;

        return true;
    }

    bool dequeue(int& value) {
        if (count == 0)
            return false;

        value = data[frontIndex];
        frontIndex = (frontIndex + 1) % data.size();
        count--;

        return true;
    }

    bool peek(int& value) {
        if (count == 0)
            return false;

        value = data[rearIndex];
        return true;
    }
};

int main() {
    CircularQueue q(3);
    int value;

    cout << (q.enqueue(10) ? "OK" : "FULL") << "\n";
    cout << (q.enqueue(20) ? "OK" : "FULL") << "\n";
    cout << (q.enqueue(30) ? "OK" : "FULL") << "\n";

    q.dequeue(value);
    cout << value << "\n";

    cout << (q.enqueue(40) ? "OK" : "FULL") << "\n";

    q.peek(value);
    cout << value << "\n";

    q.dequeue(value);
    cout << value << "\n";

    q.dequeue(value);
    cout << value << "\n";

    q.dequeue(value);
    cout << value << "\n";
}
```

